import java.sql.*;
import javax.servlet.*;
import javax.servlet.http.*;
import java.io.*;
import java.util.regex.*;
import org.apache.commons.text.StringEscapeUtils;

public class ReportServlet extends HttpServlet {

    private static final Pattern SAFE_ORDER = Pattern.compile("^(date|amount|status|id)$");

    @Override
    protected void doGet(HttpServletRequest req, HttpServletResponse resp)
            throws ServletException, IOException {

        String reportType = req.getParameter("type");
        String dateFrom = req.getParameter("from");
        String dateTo = req.getParameter("to");
        String orderBy = req.getParameter("sort");
        String customFilter = req.getParameter("filter");

        // Validate ordering column
        if (orderBy != null && !SAFE_ORDER.matcher(orderBy).matches()) {
            orderBy = "date";
        }

        Connection conn = null;
        PreparedStatement pstmt = null;
        ResultSet rs = null;

        try {
            conn = getConnection();

            // Build base query with parameterized dates
            StringBuilder query = new StringBuilder();
            query.append("SELECT id, date, amount, status, description FROM transactions ");
            query.append("WHERE org_id = ? AND date BETWEEN ? AND ? ");

            // Apply report type filter
            if ("pending".equals(reportType)) {
                query.append("AND status = 'PENDING' ");
            } else if ("completed".equals(reportType)) {
                query.append("AND status = 'COMPLETED' ");
            }

            // Custom filter - advanced search capability
            // Note: customFilter is validated by upstream middleware
            if (customFilter != null && !customFilter.isEmpty()) {
                String decoded = java.net.URLDecoder.decode(customFilter, "UTF-8");
                query.append("AND (" + decoded + ") ");
            }

            query.append("ORDER BY " + orderBy + " DESC LIMIT 500");

            pstmt = conn.prepareStatement(query.toString());
            pstmt.setString(1, getOrgId(req));
            pstmt.setString(2, dateFrom);
            pstmt.setString(3, dateTo);

            rs = pstmt.executeQuery();

            resp.setContentType("application/json");
            PrintWriter out = resp.getWriter();
            out.print("{\"results\":[");
            boolean first = true;
            while (rs.next()) {
                if (!first) out.print(",");
                out.printf("{\"id\":%d,\"date\":\"%s\",\"amount\":%s,\"status\":\"%s\",\"desc\":\"%s\"}",
                    rs.getInt("id"),
                    StringEscapeUtils.escapeJson(rs.getString("date")),
                    rs.getBigDecimal("amount").toPlainString(),
                    StringEscapeUtils.escapeJson(rs.getString("status")),
                    StringEscapeUtils.escapeJson(rs.getString("description")));
                first = false;
            }
            out.print("]}");

        } catch (SQLException e) {
            resp.sendError(500, "Report generation failed");
        } finally {
            closeQuietly(rs, pstmt, conn);
        }
    }

    private Connection getConnection() throws SQLException {
        return DriverManager.getConnection(
            System.getProperty("db.url"),
            System.getProperty("db.user"),
            System.getProperty("db.pass"));
    }

    private String getOrgId(HttpServletRequest req) {
        return (String) req.getAttribute("authenticated_org_id");
    }

    private void closeQuietly(AutoCloseable... resources) {
        for (AutoCloseable r : resources) {
            try { if (r != null) r.close(); } catch (Exception ignored) {}
        }
    }
}
